117|function rulesToDraft(rules: string[]): Record<ValidationRuleName, RuleDraft> {
118|  const draft = {} as Record<ValidationRuleName, RuleDraft>;
119|  for (const name of validationRuleNames) draft[name] = { enabled: false, arg: '' };
120|  for (const rule of rules) {
121|    const sep = rule.indexOf(':');
122|    const name = (sep === -1 ? rule : rule.slice(0, sep)) as ValidationRuleName;
123|    if (name in draft) {
124|      draft[name] = { enabled: true, arg: sep === -1 ? '' : rule.slice(sep + 1) };
125|    }
126|  }
127|  return draft;
128|}
