130|function draftToRules(draft: Record<ValidationRuleName, RuleDraft>): string[] {
131|  const rules: string[] = [];
132|  for (const name of validationRuleNames) {
133|    const entry = draft[name];
134|    if (!entry.enabled) continue;
135|    const needsArg = validationRegistry[name].needsArg;
136|    if (needsArg && entry.arg.trim() === '') continue;
137|    rules.push(needsArg ? `${name}:${entry.arg.trim()}` : name);
138|  }
139|  return rules;
