138|/** Nilai default form per tipe (create). */
139|export function formDefaultValue(field: GeneratorFieldConfig): unknown {
140|  const formType = fieldTypeRegistry[field.type].formType;
141|  if (formType === 'boolean') return false;
142|  if (formType === 'stringArray' || formType === 'rowArray') return [];
143|  if (formType === 'file') return null;
144|  return '';
