147|/** Nilai form editor baris dari baris data (number→string, file→null, default aman). */
148|export function rowFormValues(
149|  subs: GeneratorFieldConfig[],
150|  row: Record<string, unknown> | null,
151|): Record<string, unknown> {
152|  const out: Record<string, unknown> = {};
153|  for (const sub of subs) {
154|    const valueType = fieldTypeRegistry[sub.type].valueType;
155|    const raw = row?.[sub.name];
156|    if (valueType === 'number') out[sub.name] = String(raw ?? '');
157|    else if (valueType === 'file') out[sub.name] = null;
158|    else if (valueType === 'stringArray') out[sub.name] = Array.isArray(raw) ? [...raw] : [];
159|    else if (valueType === 'boolean') out[sub.name] = (raw ?? false) as boolean;
160|    else out[sub.name] = (raw ?? '') as string;
161|  }
162|  return out;
