103|  kind: 'section' | 'divider',
104|  label?: string,
105|): ModuleLayout {
106|  const used = new Set(layout.form.map((item) => item.field));
107|  let counter = layout.form.length + 1;
108|  let id = `${kind}-${counter}`;
109|  while (used.has(id)) {
110|    counter += 1;
111|    id = `${kind}-${counter}`;
112|  }
113|  const ordered = [...layout.form].sort((a, b) => a.order - b.order);
114|  const created: FormLayoutItem = {
115|    field: id,
116|    order: ordered.length,
117|    colSpan: 12,
118|    kind,
119|  };
120|  if (kind === 'section') created.label = label ?? 'Section';
121|  const next = [...ordered, created];
122|  return {
123|    ...layout,
124|    form: next.map((item, index) => ({ ...item, order: index })),
125|  };
