152|  const from = order.indexOf(activeField);
153|  const to = order.indexOf(overField);
154|  if (from === -1 || to === -1 || from === to) return layout;
155|  const [moved] = order.splice(from, 1);
156|  if (moved === undefined) return layout;
157|  order.splice(to, 0, moved);
158|  return { ...layout, detail: { order, hidden: layout.detail?.hidden ?? [] } };
