import { initialFormValue, buildFieldConfig } from '/Users/nazmudinalkhamil/Documents/Projects/generator-module-app/src/modules/generator/components/FieldForm.tsx';

function uniqueFieldName(base, existingNames) {
  const clean = base.trim() || 'field';
  if (!isReservedFieldName(clean) && !existingNames.includes(clean)) return clean;
  let counter = 2;
  while (isReservedFieldName(`${clean}${counter}`) || existingNames.includes(`${clean}${counter}`)) counter += 1;
  return `${clean}${counter}`;
}

const checks = [];
// 1. Auto-name dari label palet
for (const label of ['Text', 'Multi Select', 'Switch', 'Date Range']) {
  const base = deriveFieldNaming(label).name || label;
  checks.push([`auto-name "${label}" -> ${base}`, !!base]);
}
// 2. Duplikat + reserved
checks.push(['dup text->text2', uniqueFieldName('text', ['text']) === 'text2']);
checks.push(['reserved id->id2', uniqueFieldName('id', []) === 'id2']);
// 3. buildFieldConfig dari preset palet (multiselect)
const preset = { type: 'selectMultipleField', source: 'mockStatic', label: 'Multi Select' };
const cfg = buildFieldConfig({ ...initialFormValue(null, preset), name: 'multiSelect' });
checks.push(['multiselect options=2', (cfg.options ?? []).length === 2]);
checks.push(['multiselect name', cfg.name === 'multiSelect']);
// 4. Simulasi setRuleEnabled: min tanpa argumen harus jadi "min:3" (default placeholder)
import { validationRegistry } from '/Users/nazmudinalkhamil/Documents/Projects/generator-module-app/src/modules/generator/registry/validationRules.ts';
function defaultRuleArg(name) {
  const placeholder = validationRegistry[name].placeholder ?? '';
  const sep = placeholder.indexOf(':');
  return (sep === -1 ? placeholder : placeholder.slice(sep + 1)).trim() || '1';
}
checks.push(['default min=3', defaultRuleArg('min') === '3']);
checks.push(['default max=100', defaultRuleArg('max') === '100']);
checks.push(['default regex', defaultRuleArg('regex') === '^\\d+$']);

let fail = 0;
for (const [name, ok] of checks) { console.log(ok ? 'PASS' : 'FAIL', '-', name); if (!ok) fail += 1; }
process.exit(fail ? 1 : 0);
