1|/**
2| * Sensor pointer kustom: sama seperti PointerSensor dnd-kit, tetapi TANPA
3| * penahan klik level-dokumen.
4| *
5| * Konteks: AbstractPointerSensor.handleStart() memasang listener capture
6| * `click → stopPropagation` di document saat drag teraktivasi, lalu
7| * melepasnya 50ms setelah drag end. Di app ini pelepasan tersebut tidak
8| * pernah efektif — suppression macet selamanya dan SEMUA klik berhenti
9| * merespons setelah drop pertama (verified: bubble 0/16, stack
10| * menunjuk core.esm.js `stopPropagation`). UI kanvas sudah menjaga
11| * klik-vs-drag sendiri (guard jarak pointer di palet + stopPropagation
12| * di gagang kartu), sehingga suppression dnd-kit redundan dan aman
13| * dibuang.
14| */
15|import { PointerSensor as BasePointerSensor } from '@dnd-kit/core';
16|
17|interface SensorCoordinates {
18|  x: number;
19|  y: number;
20|}
21|
22|interface PointerSensorInternals {
23|  activated: boolean;
24|  initialCoordinates: SensorCoordinates | undefined;
25|  props: {
26|    onStart: (coordinates: SensorCoordinates) => void;
27|  };
28|  documentListeners: {
29|    add: (eventName: string, handler: () => void) => void;
30|  };
31|  removeTextSelection: () => void;
32|}
33|
34|type HandleStartFn = (this: PointerSensorInternals) => void;
35|
36|const handleStartWithoutClickSuppression: HandleStartFn = function (this) {
37|  const { initialCoordinates } = this;
38|  if (initialCoordinates) {
39|    this.activated = true;
40|    // Sengaja TIDAK memasang document click stopPropagation (lihat header).
41|    this.documentListeners.add('selectionchange', this.removeTextSelection);
42|    this.removeTextSelection();
43|    this.props.onStart(initialCoordinates);
44|  }
45|};
46|
47|class CanvasPointerSensor extends BasePointerSensor {}
48|
49|// `handleStart` bertipe private di dnd-kit — patch prototype saat runtime.
50|(CanvasPointerSensor.prototype as unknown as Record<'handleStart', HandleStartFn>).handleStart =
51|  handleStartWithoutClickSuppression;
52|
53|export default CanvasPointerSensor;

